 public History requireHistory(FormalEvaluationNodeRuntime.Session s,JsonNode modelResults,JsonNode modelPins)throws Exception {s.requireCurrent();var j=s.lease().job();var data=history(j.tenantId(),j.runId(),s.lease().stepId(),s.sessionId(),modelResults,modelPins);for(var pin:data.required("tool_pins")){var body=verified(one(rows(j.tenantId(),j.runId(),s.lease().stepId(),s.sessionId(),text(pin,"tool_receipt_id"))));same(s.binding(),body.required("binding"));same(authorize(s,text(body,"tool_id"),body.required("request")).pins,body.required("authority"));if("AT-08".equals(text(body,"tool_id")))throw new TenantAccessException(ErrorCode.STEP_NOT_READY);}return new History(s,modelResults,modelPins,data);}
 /** Immutable original tool receipts for independent business coverage; caller claims are never reads. */
 public List<JsonNode> businessOriginals(EnterpriseAccess.Admission a,String run,String step,String session)throws Exception {
  FormalEvaluationExecutionAdmission.current(a);WireValues.uuid(run);WireValues.uuid(step);WireValues.uuid(session);
  var found=db.queryForList("SELECT * FROM formal_evaluation_tool_receipt WHERE tenant_id=? AND run_id=? AND step_id=? AND session_id=? ORDER BY created_at,receipt_id LIMIT 257",a.context().tenant_id(),run,step,session);
  if(found.size()>256)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);var result=new ArrayList<JsonNode>();for(var row:found)result.add(verified(row).deepCopy());return List.copyOf(result);
 }
 public void requireCompleteOriginal(EnterpriseAccess.Admission a,String run,String step,String session)throws Exception {FormalEvaluationExecutionAdmission.current(a);WireValues.uuid(run);WireValues.uuid(step);WireValues.uuid(session);var rows=db.queryForList("SELECT * FROM formal_evaluation_tool_receipt WHERE tenant_id=? AND run_id=? AND step_id=? AND session_id=? ORDER BY created_at,receipt_id LIMIT 257",a.context().tenant_id(),run,step,session);if(rows.size()>256)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);for(var row:rows){var original=verified(row);if("AT-08".equals(text(original,"tool_id")))throw new TenantAccessException(ErrorCode.STEP_NOT_READY);}}
 public void requireOriginal(String tenant,String run,String step,String session,JsonNode history)throws Exception {var original=history(tenant,run,step,session,history.required("model_results"),history.required("model_pins"));same(original.required("tool_responses"),history.required("tool_responses"));same(original.required("tool_pins"),history.required("tool_pins"));}
 private ObjectNode history(String tenant,String run,String step,String session,JsonNode results,JsonNode modelPins)throws Exception {if(!results.isArray()||!modelPins.isArray()||results.size()!=modelPins.size())bad();var data=TaskInvocationHistoryData.empty();data.set("model_results",results.deepCopy());data.set("model_pins",modelPins.deepCopy());var roots=new TreeSet<String>();int count=0;for(var result:results)for(var block:result.required("blocks"))if("tool-call".equals(text(block,"type"))){if(++count>256)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);String id=receiptId(session,text(block,"id"));var row=one(rows(tenant,run,step,session,id));var body=verified(row);same(text(result,"invocation_id"),text(body.required("tool_call"),"invocation_id"));same(session,text(body.required("tool_call"),"session_id"));var response=((com.fasterxml.jackson.databind.node.ArrayNode)data.required("tool_responses")).addObject().put("invocation_id",text(result,"invocation_id")).put("tool_call_id",text(block,"id"));response.set("response",body.required("response"));var pin=((com.fasterxml.jackson.databind.node.ArrayNode)data.required("tool_pins")).addObject().put("tool_receipt_id",id).put("tool_receipt_sha256",(String)row.get("receipt_sha256")).put("response_sha256",text(body,"response_sha256"));pin.set("tool_call",body.required("tool_call"));for(var root:body.required("content_roots"))roots.add(root.asText());}TaskInvocationHistoryData.require(data,results.size()+1L);return data;}
 public final class History {private final FormalEvaluationNodeRuntime.Session session;private final JsonNode results,pins,data;private History(FormalEvaluationNodeRuntime.Session s,JsonNode r,JsonNode p,JsonNode d){session=s;results=r.deepCopy();pins=p.deepCopy();data=d.deepCopy();}public JsonNode data(){return data.deepCopy();}public void requireCurrent(FormalEvaluationNodeRuntime.Session s)throws Exception {same(session.sessionId(),s.sessionId());same(data,requireHistory(s,results,pins).data);}public JsonNode requireModelSend(FormalEvaluationNodeRuntime.Session s,String provider)throws Exception {requireCurrent(s);if(data.required("tool_pins").isEmpty())return json.object();var sent=json.object();sent.set("fixed_context",s.lease().input().context().requireModelSend(s.admission(),provider));sent.put("history_sha256",hash(data));return sent;}public List<String> contentRoots()throws Exception {var roots=new TreeSet<String>();var j=session.lease().job();for(var pin:data.required("tool_pins"))for(var root:verified(one(rows(j.tenantId(),j.runId(),session.lease().stepId(),session.sessionId(),text(pin,"tool_receipt_id")))).required("content_roots"))roots.add(root.asText());return List.copyOf(roots);}}
 private static String receiptId(String session,String call){return UUID.nameUUIDFromBytes(("EVAL_TOOL|"+session+"|"+call).getBytes(StandardCharsets.UTF_8)).toString();}
 private static String utf8(byte[] bytes)throws Exception{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes)).toString();}
 private static boolean contains(JsonNode array,JsonNode value){for(var item:array)if(item.equals(value))return true;return false;}private static String text(JsonNode n,String f){return TaskInvocationHistoryData.text(n,f);}private static String hash(JsonNode n){return TaskInvocationHistoryData.digest(n);}private static <T>T one(List<T> v){if(v.size()!=1)bad();return v.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void changed(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
